package io.xeros.solo;
import io.xeros.*;import io.xeros.content.minigames.raids.*;import io.xeros.content.minigames.inferno.*;import io.xeros.content.minigames.pest_control.*;import io.xeros.content.item.lootable.*;import io.xeros.content.item.lootable.impl.*;import io.xeros.content.combat.*;import io.xeros.content.combat.core.AttackNpcCheck;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import io.xeros.model.items.GameItem;import java.util.*;import java.lang.reflect.*;import java.util.function.IntUnaryOperator;
public final class SoloActivitiesSafetyCheck {
 static void ok(boolean b,String s){SoloActivitiesPlayableCheck.ok(b,s);}static Player actor(String n){return SoloActivitiesPlayableCheck.actor(n);}static void clear(Player p){SoloActivitiesPlayableCheck.clear(p);}static void tick(Player p,int n){SoloActivitiesPlayableCheck.tick(p,n);}static void apply(Player p){SoloActivitiesPlayableCheck.apply(p);}static void kill(Player p,NPC n){SoloActivitiesPlayableCheck.kill(p,n);}static void fill(Player p){while(p.getItems().freeSlots()>0)p.getItems().addItem(526,1);}
 static void guards(){for(int mode=0;mode<4;mode++){for(int activity=0;activity<3;activity++){Player p=actor("guard66qa");if(mode==0)p.isDead=true;if(mode==1)p.getHealth().setCurrentHealth(0);if(mode==2)p.isBanking=true;if(mode==3)p.teleTimer=2;if(activity==0)SoloCox.enter(p);if(activity==1)Inferno.startInferno(p,0);if(activity==2)SoloPest.enter(p);ok(p.getInstance()==null,"Unsafe entry "+mode+" "+activity);clear(p);}}Player p=actor("level66qa");p.combatLevel=3;ok(!SoloPest.enter(p),"Pest level 40 gate");clear(p);System.out.println("SOLO_THREE_ACTIVITIES_DEAD_ZERO_HP_BANK_TELEPORT_AND_PEST_COMBAT_40_GUARDS_PASS");}
 static void cox()throws Exception{Player p=actor("coxloot66qa");p.coxSoloStage=11;SoloCox.enter(p);apply(p);SoloCox a=(SoloCox)p.getInstance();List<GameItem> rares=RaidsChestItems.getItems().get(LootRarity.RARE);int k=-1;for(int i=0;i<rares.size();i++)if(rares.get(i).getId()==20997){k=i;break;}ok(k>=0,"Twisted bow absent");final int chosen=k;Field f=SoloCox.class.getDeclaredField("lootRoll");f.setAccessible(true);f.set(a,(IntUnaryOperator)(b->b==25?0:chosen));NPC head=a.getNpcs().stream().filter(n->n.getNpcId()==7554).findFirst().get();ok(!AttackNpcCheck.check(p,head,false),"Olm head before hands");fill(p);for(NPC n:new ArrayList<>(a.getNpcs()))if(n.getNpcId()!=7554)kill(p,n);ok(p.getRaidsInstance().leftHand&&p.getRaidsInstance().rightHand,"Olm hands not credited");kill(p,head);tick(p,8);ok(p.getItems().bankContains(20997)&&p.raidCount==1&&p.coxSoloStage==0,"Twisted bow full-bag completion");tick(p,30);ok(p.raidCount==1,"Duplicate Chambers reward");PlayerSave.saveGameInstant(p);Player q=SoloActivitiesPlayableCheck.reload("coxloot66qa");q.getCollectionLog().loadForPlayer(q);ok(q.getItems().bankContains(20997)&&q.raidCount==1&&q.getCollectionLog().getUnlocked(7554).stream().anyMatch(i->i.getId()==20997),"Twisted bow and collection log reload");clear(p);clear(q);System.out.println("COX_OLM_HAND_GATE_TWISTED_BOW_FULL_BAG_BANK_SINGLE_CLEAR_REAL_SAVE_RELOAD_PASS");}
 static void inferno()throws Exception{Player p=actor("zukphases66qa");p.infernoSoloWave=68;Inferno.startInferno(p,0);apply(p);Inferno a=p.getInferno();tick(p,35);NPC z=a.getNpcs().stream().filter(n->n.getNpcId()==7706).findFirst().get();z.appendDamage(p,800,Hitmark.HIT);tick(p,12);ok(a.getNpcs().stream().anyMatch(n->n.getNpcId()==7700),"Zuk Jad phase");z.appendDamage(p,200,Hitmark.HIT);tick(p,20);ok(a.getNpcs().stream().anyMatch(n->n.getNpcId()==7708),"Zuk healer phase");int hp=p.getHealth().getCurrentHealth();a.leaveGame();apply(p);tick(p,100);ok(p.getHealth().getCurrentHealth()==hp&&p.infernoSoloCompletions==0&&p.infernoSoloWave==68,"Zuk delayed hit/reward after exit");clear(p);System.out.println("INFERNO_ZUK_JAD_AND_HEALER_THRESHOLDS_DELAYED_SPECIAL_CANCEL_AFTER_LEAVE_PASS");}
 static void pest()throws Exception{Player p=actor("pestsafety66qa");SoloPest.enter(p);apply(p);SoloPest a=(SoloPest)p.getInstance();ok(!SoloPest.enter(p),"Duplicate Pest instance");NPC knight=a.getNpcs().stream().filter(n->n.getNpcId()==1756).findFirst().get();ok(!knight.canBeAttacked(p),"Player can attack Void Knight");tick(p,1);NPC enemy=a.getNpcs().stream().filter(n->n.getNpcId()==1693).findFirst().get();enemy.absX=knight.absX+1;enemy.absY=knight.absY;int hp=knight.getHealth().getCurrentHealth();tick(p,5);ok(knight.getHealth().getCurrentHealth()<hp,"Pest enemy cannot hurt Knight");knight.appendDamage(enemy,knight.getHealth().getCurrentHealth(),Hitmark.HIT);tick(p,1);ok(p.getInstance()==null&&p.pcPoints==0,"Knight death gives win");clear(p);
 p=actor("pestgates66qa");SoloPest.enter(p);apply(p);a=(SoloPest)p.getInstance();BossRoutesCheck.at(p,2643,2592,a.getHeight());SoloPest.crossGate(p,2643,2592);apply(p);ok(p.absX==2644&&p.heightLevel==a.getHeight()&&p.getInstance()==a,"Pest gate lost private height");p.isDead=true;p.getHealth().setCurrentHealth(0);ok(a.handleDeath(p)&&p.getInstance()==null&&p.pcPoints==0,"Pest safe player death");clear(p);
 p=actor("pestxp66qa");p.pcPoints=100;p.skillLock[0]=true;int xp=p.playerXP[0];p.getPestControlRewards().click(144150);p.getPestControlRewards().click(144138);ok(p.pcPoints==100&&p.playerXP[0]==xp,"XP lock charged points");p.skillLock[0]=false;p.expLock=false;p.getPestControlRewards().click(144138);ok(p.pcPoints==99&&p.playerXP[0]>xp,"Pest XP buy");PlayerSave.saveGameInstant(p);Player q=SoloActivitiesPlayableCheck.reload("pestxp66qa");ok(q.pcPoints==99&&q.playerXP[0]==p.playerXP[0],"XP purchase reload");clear(p);clear(q);
 p=actor("pestpack66qa");p.pcPoints=100;fill(p);p.getPestControlRewards().click(144189);p.getPestControlRewards().click(144138);ok(p.pcPoints==100,"Pack charged full bag");p.getItems().deleteItem2(526,10);p.getPestControlRewards().click(144138);ok(p.pcPoints==70,"Herb pack buy");clear(p);System.out.println("PEST_VOID_KNIGHT_DAMAGE_LOSS_SAFE_DEATH_PRIVATE_GATE_XP_LOCK_ATOMIC_PACK_AND_XP_SAVE_PASS");}
 public static void main(String[]a)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;guards();cox();inferno();pest();System.out.println("SOLO_ACTIVITIES_SAFETY_V66_PASS");System.exit(0);}
}
